using System.Text;

namespace BatchRenameStudio.Core;

/// <summary>
/// File-name primitives shared by the planner, the CLI and the GUI.
/// Every method here implements a numbered rule of the naming contract literally;
/// the rule number is quoted in each doc comment so the code can be diffed against the spec.
/// </summary>
public static class NameUtil
{
    /// <summary>Characters that make a proposed name invalid (contract rule 13).</summary>
    public static readonly char[] InvalidNameChars = { '<', '>', ':', '"', '/', '\\', '|', '?', '*' };

    /// <summary>Windows reserved device names (contract rule 13), compared case-insensitively.</summary>
    public static readonly IReadOnlySet<string> ReservedDeviceNames = BuildReservedNames();

    public const int MaxNameLength = 255;

    private static HashSet<string> BuildReservedNames()
    {
        var set = new HashSet<string>(StringComparer.OrdinalIgnoreCase) { "CON", "PRN", "AUX", "NUL" };
        for (int i = 1; i <= 9; i++)
        {
            set.Add("COM" + i);
            set.Add("LPT" + i);
        }
        return set;
    }

    /// <summary>
    /// Contract rule 2. Splits on the LAST '.' only when its index is &gt; 0.
    /// The returned extension never contains the dot. ".gitignore" -&gt; ("./gitignore" base, "" ext).
    /// </summary>
    public static (string Base, string Ext) Split(string name)
    {
        int dot = name.LastIndexOf('.');
        if (dot > 0)
        {
            return (name.Substring(0, dot), name.Substring(dot + 1));
        }
        return (name, string.Empty);
    }

    /// <summary>Contract rule 12: base + "." + ext when ext is non-empty, otherwise base.</summary>
    public static string Join(string baseName, string ext)
        => ext.Length == 0 ? baseName : baseName + "." + ext;

    /// <summary>
    /// Contract rule 13, first bullet. Returns a short human-readable reason when invalid,
    /// or null when the name passes every validity test.
    /// </summary>
    public static string? DescribeInvalid(string proposed)
    {
        if (proposed.Length == 0)
        {
            return "empty name";
        }
        if (proposed.Length > MaxNameLength)
        {
            return "longer than " + MaxNameLength + " characters";
        }
        foreach (char c in proposed)
        {
            if (c < ' ')
            {
                return "contains a control character";
            }
            if (Array.IndexOf(InvalidNameChars, c) >= 0)
            {
                return "contains the illegal character '" + c + "'";
            }
        }
        var (baseName, _) = Split(proposed);
        if (ReservedDeviceNames.Contains(baseName))
        {
            return "reserved device name '" + baseName + "'";
        }
        return null;
    }

    public static bool IsInvalid(string proposed) => DescribeInvalid(proposed) is not null;

    /// <summary>
    /// Contract rule 10, "title" mode: every maximal run of Unicode letters gets its first
    /// character upper-cased and the rest lower-cased; non-letters are copied untouched.
    /// </summary>
    public static string ToTitleCase(string s)
    {
        var sb = new StringBuilder(s.Length);
        bool atRunStart = true;
        foreach (char c in s)
        {
            if (char.IsLetter(c))
            {
                sb.Append(atRunStart ? char.ToUpperInvariant(c) : char.ToLowerInvariant(c));
                atRunStart = false;
            }
            else
            {
                sb.Append(c);
                atRunStart = true;
            }
        }
        return sb.ToString();
    }

    /// <summary>
    /// Case-sensitive or case-insensitive literal replace-all. Unlike Regex.Replace the
    /// replacement text stays literal, so a '$' in <paramref name="replaceWith"/> is not a group reference.
    /// </summary>
    public static string LiteralReplaceAll(string input, string find, string replaceWith, bool ignoreCase)
    {
        if (find.Length == 0)
        {
            return input;
        }
        var comparison = ignoreCase ? StringComparison.OrdinalIgnoreCase : StringComparison.Ordinal;
        var sb = new StringBuilder(input.Length);
        int pos = 0;
        while (true)
        {
            int hit = input.IndexOf(find, pos, comparison);
            if (hit < 0)
            {
                sb.Append(input, pos, input.Length - pos);
                return sb.ToString();
            }
            sb.Append(input, pos, hit - pos);
            sb.Append(replaceWith);
            pos = hit + find.Length;
        }
    }

    public static int Clamp(int value, int min, int max)
    {
        if (value < min) return min;
        if (value > max) return max;
        return value;
    }
}

