using System.Text;
using System.Text.RegularExpressions;

namespace BatchRenameStudio.Core;

public enum ApplyTo
{
    Name,
    NameAndExtension
}

public enum SortMode
{
    Name,
    Created,
    Modified
}

public enum InsertPosition
{
    Prefix,
    Suffix,
    Index
}

public enum AffixPosition
{
    Prefix,
    Suffix
}

public enum CaseMode
{
    Upper,
    Lower,
    Title
}

public enum ExtensionMode
{
    Lower,
    Upper,
    Set
}

/// <summary>
/// One entry of the "steps" array. A step either transforms the target string
/// (<see cref="Apply"/>) or the extension (<see cref="IsExtensionStep"/>); never both.
/// </summary>
public abstract class RuleStep
{
    public abstract string Op { get; }

    /// <summary>Contract rule 11: the "extension" op is routed to the extension, whatever applyTo says.</summary>
    public virtual bool IsExtensionStep => false;

    /// <summary>Transforms the target string. <paramref name="ordinal"/> is the 0-based processing index.</summary>
    public virtual string Apply(string target, int ordinal) => target;

    /// <summary>Transforms the extension (without its dot). Only called for extension steps.</summary>
    public virtual string ApplyToExtension(string ext) => ext;

    /// <summary>Short one-line description shown in the GUI rule list.</summary>
    public abstract string Describe();

    /// <summary>Deep copy, used by the GUI editor so cancelling an edit changes nothing.</summary>
    public abstract RuleStep Clone();
}

public sealed class ReplaceStep : RuleStep
{
    public string Find { get; set; } = string.Empty;
    public string ReplaceWith { get; set; } = string.Empty;
    public bool Regex { get; set; }
    public bool IgnoreCase { get; set; }

    private Regex? _compiled;

    public override string Op => "replace";

    /// <summary>
    /// Builds (and caches) the regex. Throws <see cref="RuleException"/> on a malformed pattern
    /// so the CLI can fail loudly instead of silently producing a wrong plan.
    /// </summary>
    public Regex CompiledRegex()
    {
        if (_compiled is null)
        {
            var options = RegexOptions.CultureInvariant;
            if (IgnoreCase)
            {
                options |= RegexOptions.IgnoreCase;
            }
            try
            {
                _compiled = new Regex(Find, options);
            }
            catch (ArgumentException ex)
            {
                throw new RuleException("invalid regular expression \"" + Find + "\": " + ex.Message);
            }
        }
        return _compiled;
    }

    public void Invalidate() => _compiled = null;

    public override string Apply(string target, int ordinal)
    {
        if (Regex)
        {
            return CompiledRegex().Replace(target, ReplaceWith);
        }
        return NameUtil.LiteralReplaceAll(target, Find, ReplaceWith, IgnoreCase);
    }

    public override string Describe()
    {
        var flags = new List<string>();
        if (Regex) flags.Add("regex");
        if (IgnoreCase) flags.Add("ignore case");
        string suffix = flags.Count == 0 ? string.Empty : "  [" + string.Join(", ", flags) + "]";
        return "Replace \"" + Find + "\" -> \"" + ReplaceWith + "\"" + suffix;
    }

    public override RuleStep Clone() => new ReplaceStep
    {
        Find = Find,
        ReplaceWith = ReplaceWith,
        Regex = Regex,
        IgnoreCase = IgnoreCase
    };
}

public sealed class InsertStep : RuleStep
{
    public string Text { get; set; } = string.Empty;
    public InsertPosition Position { get; set; } = InsertPosition.Prefix;
    public int Index { get; set; }

    public override string Op => "insert";

    public override string Apply(string target, int ordinal)
    {
        switch (Position)
        {
            case InsertPosition.Prefix:
                return Text + target;
            case InsertPosition.Suffix:
                return target + Text;
            default:
                int at = NameUtil.Clamp(Index, 0, target.Length);
                return target.Insert(at, Text);
        }
    }

    public override string Describe()
    {
        string where = Position switch
        {
            InsertPosition.Prefix => "as prefix",
            InsertPosition.Suffix => "as suffix",
            _ => "at index " + Index
        };
        return "Insert \"" + Text + "\" " + where;
    }

    public override RuleStep Clone() => new InsertStep { Text = Text, Position = Position, Index = Index };
}

public sealed class RemoveStep : RuleStep
{
    public int From { get; set; }
    public int Count { get; set; }

    public override string Op => "remove";

    public override string Apply(string target, int ordinal)
    {
        int from = NameUtil.Clamp(From, 0, target.Length);
        int count = NameUtil.Clamp(Count, 0, target.Length - from);
        return target.Remove(from, count);
    }

    public override string Describe() => "Remove " + Count + " char(s) from index " + From;

    public override RuleStep Clone() => new RemoveStep { From = From, Count = Count };
}

public sealed class SequenceStep : RuleStep
{
    private static readonly Regex TokenPattern = new(@"\{n:(0+)\}", RegexOptions.CultureInvariant);

    public string Pattern { get; set; } = "{n:000}_";
    public int Start { get; set; } = 1;
    public int Step { get; set; } = 1;
    public AffixPosition Position { get; set; } = AffixPosition.Prefix;

    public override string Op => "sequence";

    /// <summary>
    /// Contract rule 9. The counter is start + ordinal * step, so it advances for every file in
    /// processing order regardless of that file's final status.
    /// </summary>
    public string Render(int ordinal)
    {
        long counter = (long)Start + (long)ordinal * Step;
        var match = TokenPattern.Match(Pattern);
        if (!match.Success)
        {
            return Pattern;
        }
        int width = match.Groups[1].Value.Length;
        string number = counter.ToString(new string('0', width), System.Globalization.CultureInfo.InvariantCulture);
        var sb = new StringBuilder(Pattern.Length + width);
        sb.Append(Pattern, 0, match.Index);
        sb.Append(number);
        sb.Append(Pattern, match.Index + match.Length, Pattern.Length - match.Index - match.Length);
        return sb.ToString();
    }

    public override string Apply(string target, int ordinal)
    {
        string rendered = Render(ordinal);
        return Position == AffixPosition.Prefix ? rendered + target : target + rendered;
    }

    public override string Describe()
        => "Sequence \"" + Pattern + "\" from " + Start + " step " + Step + " as " + Position.ToString().ToLowerInvariant();

    public override RuleStep Clone()
        => new SequenceStep { Pattern = Pattern, Start = Start, Step = Step, Position = Position };
}

public sealed class CaseStep : RuleStep
{
    public CaseMode Mode { get; set; } = CaseMode.Lower;

    public override string Op => "case";

    public override string Apply(string target, int ordinal) => Transform(target, Mode);

    internal static string Transform(string s, CaseMode mode) => mode switch
    {
        CaseMode.Upper => s.ToUpperInvariant(),
        CaseMode.Lower => s.ToLowerInvariant(),
        _ => NameUtil.ToTitleCase(s)
    };

    public override string Describe() => "Case -> " + Mode.ToString().ToLowerInvariant();

    public override RuleStep Clone() => new CaseStep { Mode = Mode };
}

public sealed class ExtensionStep : RuleStep
{
    public ExtensionMode Mode { get; set; } = ExtensionMode.Lower;
    public string Value { get; set; } = string.Empty;

    public override string Op => "extension";

    public override bool IsExtensionStep => true;

    public override string ApplyToExtension(string ext) => Mode switch
    {
        ExtensionMode.Lower => ext.ToLowerInvariant(),
        ExtensionMode.Upper => ext.ToUpperInvariant(),
        _ => Value
    };

    public override string Describe()
        => Mode == ExtensionMode.Set
            ? "Extension -> set \"" + Value + "\""
            : "Extension -> " + Mode.ToString().ToLowerInvariant();

    public override RuleStep Clone() => new ExtensionStep { Mode = Mode, Value = Value };
}

/// <summary>Raised for any rule set that cannot be honoured (bad JSON, bad regex, unknown op).</summary>
public sealed class RuleException : Exception
{
    public RuleException(string message) : base(message)
    {
    }
}

