namespace BatchRenameStudio.Core;

/// <summary>The whole rules.json document: what the steps operate on, in which order files are visited.</summary>
public sealed class RuleSet
{
    public ApplyTo ApplyTo { get; set; } = ApplyTo.Name;

    public SortMode Sort { get; set; } = SortMode.Name;

    public List<RuleStep> Steps { get; } = new();

    public RuleSet Clone()
    {
        var copy = new RuleSet { ApplyTo = ApplyTo, Sort = Sort };
        foreach (var step in Steps)
        {
            copy.Steps.Add(step.Clone());
        }
        return copy;
    }

    /// <summary>
    /// Forces every lazily-compiled part of the rule set to be built now, so a malformed
    /// pattern is reported before any file is touched rather than mid-run.
    /// </summary>
    public void Validate()
    {
        foreach (var step in Steps)
        {
            if (step is ReplaceStep { Regex: true } replace)
            {
                replace.Invalidate();
                replace.CompiledRegex();
            }
        }
    }
}

