namespace BatchRenameStudio.Core;

/// <summary>
/// Turns a folder listing plus a rule set into a <see cref="Plan"/>.
/// Pure and deterministic: same inputs, same output, no filesystem access, no clock, no culture.
/// </summary>
public static class RenamePlanner
{
    /// <summary>
    /// Contract rule 1: regular files directly inside <paramref name="directory"/>, non-recursive,
    /// directories excluded entirely.
    /// </summary>
    public static List<FileEntry> ReadFolder(string directory)
    {
        var entries = new List<FileEntry>();
        var info = new DirectoryInfo(directory);
        foreach (var file in info.EnumerateFiles("*", SearchOption.TopDirectoryOnly))
        {
            entries.Add(new FileEntry(file.Name, file.CreationTimeUtc, file.LastWriteTimeUtc));
        }
        return entries;
    }

    /// <summary>
    /// Contract rule 5 and 14. The name comparison is ordinal (codepoint) ascending and
    /// case-sensitive; timestamp sorts fall back to the same ordinal comparison so that two files
    /// sharing a timestamp still produce a byte-identical plan (contract rule 15).
    /// </summary>
    public static List<FileEntry> SortForProcessing(IEnumerable<FileEntry> files, SortMode sort)
    {
        var list = new List<FileEntry>(files);
        Comparison<FileEntry> comparison = sort switch
        {
            SortMode.Created => (a, b) =>
            {
                int c = a.CreatedUtc.CompareTo(b.CreatedUtc);
                return c != 0 ? c : string.CompareOrdinal(a.Name, b.Name);
            },
            SortMode.Modified => (a, b) =>
            {
                int c = a.ModifiedUtc.CompareTo(b.ModifiedUtc);
                return c != 0 ? c : string.CompareOrdinal(a.Name, b.Name);
            },
            _ => (a, b) => string.CompareOrdinal(a.Name, b.Name)
        };
        // List.Sort is unstable, so the comparison above is a total order on distinct file names.
        list.Sort(comparison);
        return list;
    }

    public static Plan Create(IEnumerable<FileEntry> files, RuleSet rules)
    {
        rules.Validate();

        var ordered = SortForProcessing(files, rules.Sort);

        var proposals = new List<string>(ordered.Count);
        for (int i = 0; i < ordered.Count; i++)
        {
            proposals.Add(Propose(ordered[i].Name, rules, i));
        }

        var existingNames = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        foreach (var entry in ordered)
        {
            existingNames.Add(entry.Name);
        }

        var proposedCounts = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
        foreach (var proposed in proposals)
        {
            proposedCounts.TryGetValue(proposed, out int count);
            proposedCounts[proposed] = count + 1;
        }

        var items = new List<PlanItem>(ordered.Count);
        var summary = new PlanSummary { Total = ordered.Count };

        for (int i = 0; i < ordered.Count; i++)
        {
            string original = ordered[i].Name;
            string proposed = proposals[i];
            var (status, reason) = Classify(original, proposed, existingNames, proposedCounts);

            items.Add(new PlanItem(original, proposed, status, reason));
            switch (status)
            {
                case PlanStatus.Ok: summary.Ok++; break;
                case PlanStatus.Collision: summary.Collision++; break;
                case PlanStatus.Unchanged: summary.Unchanged++; break;
                case PlanStatus.Invalid: summary.Invalid++; break;
            }
        }

        return new Plan(items, summary);
    }

    /// <summary>
    /// Contract rules 2, 3, 4, 11 and 12: build the proposed file name for one file.
    /// <paramref name="ordinal"/> is the 0-based position in processing order and feeds the sequence counter.
    /// </summary>
    public static string Propose(string fileName, RuleSet rules, int ordinal)
    {
        if (rules.ApplyTo == ApplyTo.Name)
        {
            var (baseName, ext) = NameUtil.Split(fileName);
            foreach (var step in rules.Steps)
            {
                if (step.IsExtensionStep)
                {
                    ext = step.ApplyToExtension(ext);
                }
                else
                {
                    baseName = step.Apply(baseName, ordinal);
                }
            }
            return NameUtil.Join(baseName, ext);
        }

        // applyTo == nameAndExtension: the target string IS the whole (evolving) file name.
        // An extension step re-splits the current string and rewrites its trailing extension.
        string target = fileName;
        foreach (var step in rules.Steps)
        {
            if (step.IsExtensionStep)
            {
                var (b, e) = NameUtil.Split(target);
                target = NameUtil.Join(b, step.ApplyToExtension(e));
            }
            else
            {
                target = step.Apply(target, ordinal);
            }
        }
        return target;
    }

    /// <summary>Contract rule 13: invalid &gt; collision &gt; unchanged &gt; ok, first match wins.</summary>
    private static (string Status, string Reason) Classify(
        string original,
        string proposed,
        HashSet<string> existingNames,
        Dictionary<string, int> proposedCounts)
    {
        string? invalidReason = NameUtil.DescribeInvalid(proposed);
        if (invalidReason is not null)
        {
            return (PlanStatus.Invalid, invalidReason);
        }

        bool hitsAnotherExistingFile =
            existingNames.Contains(proposed) &&
            !string.Equals(proposed, original, StringComparison.OrdinalIgnoreCase);

        if (hitsAnotherExistingFile)
        {
            return (PlanStatus.Collision, "an existing file already uses this name");
        }

        if (proposedCounts.TryGetValue(proposed, out int count) && count > 1)
        {
            return (PlanStatus.Collision, "another file is renamed to the same name");
        }

        if (string.Equals(proposed, original, StringComparison.Ordinal))
        {
            return (PlanStatus.Unchanged, "the rules produce the original name");
        }

        return (PlanStatus.Ok, string.Empty);
    }
}

