using System.Text;
using System.Text.Encodings.Web;
using System.Text.Json;

namespace BatchRenameStudio.Core;

/// <summary>Reads and writes the rules.json document defined by the fixed contract.</summary>
public static class RulesJson
{
    private static readonly UTF8Encoding Utf8NoBom = new(encoderShouldEmitUTF8Identifier: false);

    public static RuleSet Load(string path)
    {
        string text;
        try
        {
            text = File.ReadAllText(path);
        }
        catch (Exception ex) when (ex is IOException or UnauthorizedAccessException)
        {
            throw new RuleException("cannot read rules file \"" + path + "\": " + ex.Message);
        }
        return Parse(text);
    }

    public static RuleSet Parse(string json)
    {
        JsonDocument document;
        try
        {
            document = JsonDocument.Parse(json, new JsonDocumentOptions
            {
                CommentHandling = JsonCommentHandling.Skip,
                AllowTrailingCommas = true
            });
        }
        catch (JsonException ex)
        {
            throw new RuleException("rules file is not valid JSON: " + ex.Message);
        }

        using (document)
        {
            var root = document.RootElement;
            if (root.ValueKind != JsonValueKind.Object)
            {
                throw new RuleException("rules file must contain a JSON object at the top level");
            }

            var rules = new RuleSet
            {
                ApplyTo = ParseApplyTo(OptionalString(root, "applyTo") ?? "name"),
                Sort = ParseSort(OptionalString(root, "sort") ?? "name")
            };

            if (root.TryGetProperty("steps", out var steps))
            {
                if (steps.ValueKind != JsonValueKind.Array)
                {
                    throw new RuleException("\"steps\" must be an array");
                }
                int index = 0;
                foreach (var step in steps.EnumerateArray())
                {
                    if (step.ValueKind != JsonValueKind.Object)
                    {
                        throw new RuleException("steps[" + index + "] must be an object");
                    }
                    rules.Steps.Add(ParseStep(step, index));
                    index++;
                }
            }

            rules.Validate();
            return rules;
        }
    }

    private static RuleStep ParseStep(JsonElement element, int index)
    {
        string op = (OptionalString(element, "op") ?? string.Empty).Trim();
        switch (op.ToLowerInvariant())
        {
            case "replace":
                return new ReplaceStep
                {
                    Find = OptionalString(element, "find") ?? string.Empty,
                    ReplaceWith = OptionalString(element, "replaceWith") ?? string.Empty,
                    Regex = OptionalBool(element, "regex") ?? false,
                    IgnoreCase = OptionalBool(element, "ignoreCase") ?? false
                };

            case "insert":
                return new InsertStep
                {
                    Text = OptionalString(element, "text") ?? string.Empty,
                    Position = ParseInsertPosition(OptionalString(element, "position") ?? "prefix", index),
                    Index = OptionalInt(element, "index") ?? 0
                };

            case "remove":
                return new RemoveStep
                {
                    From = OptionalInt(element, "from") ?? 0,
                    Count = OptionalInt(element, "count") ?? 0
                };

            case "sequence":
                return new SequenceStep
                {
                    Pattern = OptionalString(element, "pattern") ?? "{n:000}",
                    Start = OptionalInt(element, "start") ?? 1,
                    Step = OptionalInt(element, "step") ?? 1,
                    Position = ParseAffixPosition(OptionalString(element, "position") ?? "prefix", index)
                };

            case "case":
                return new CaseStep { Mode = ParseCaseMode(OptionalString(element, "mode") ?? "lower", index) };

            case "extension":
                return new ExtensionStep
                {
                    Mode = ParseExtensionMode(OptionalString(element, "mode") ?? "lower", index),
                    Value = OptionalString(element, "value") ?? string.Empty
                };

            default:
                throw new RuleException("steps[" + index + "]: unknown op \"" + op + "\"");
        }
    }

    private static ApplyTo ParseApplyTo(string value) => value.Trim().ToLowerInvariant() switch
    {
        "name" => ApplyTo.Name,
        "nameandextension" => ApplyTo.NameAndExtension,
        _ => throw new RuleException("\"applyTo\" must be \"name\" or \"nameAndExtension\" (got \"" + value + "\")")
    };

    private static SortMode ParseSort(string value) => value.Trim().ToLowerInvariant() switch
    {
        "name" => SortMode.Name,
        "created" => SortMode.Created,
        "modified" => SortMode.Modified,
        _ => throw new RuleException("\"sort\" must be \"name\", \"created\" or \"modified\" (got \"" + value + "\")")
    };

    private static InsertPosition ParseInsertPosition(string value, int index) => value.Trim().ToLowerInvariant() switch
    {
        "prefix" => InsertPosition.Prefix,
        "suffix" => InsertPosition.Suffix,
        "index" => InsertPosition.Index,
        _ => throw new RuleException("steps[" + index + "]: \"position\" must be \"prefix\", \"suffix\" or \"index\"")
    };

    private static AffixPosition ParseAffixPosition(string value, int index) => value.Trim().ToLowerInvariant() switch
    {
        "prefix" => AffixPosition.Prefix,
        "suffix" => AffixPosition.Suffix,
        _ => throw new RuleException("steps[" + index + "]: \"position\" must be \"prefix\" or \"suffix\"")
    };

    private static CaseMode ParseCaseMode(string value, int index) => value.Trim().ToLowerInvariant() switch
    {
        "upper" => CaseMode.Upper,
        "lower" => CaseMode.Lower,
        "title" => CaseMode.Title,
        _ => throw new RuleException("steps[" + index + "]: \"mode\" must be \"upper\", \"lower\" or \"title\"")
    };

    private static ExtensionMode ParseExtensionMode(string value, int index) => value.Trim().ToLowerInvariant() switch
    {
        "lower" => ExtensionMode.Lower,
        "upper" => ExtensionMode.Upper,
        "set" => ExtensionMode.Set,
        _ => throw new RuleException("steps[" + index + "]: \"mode\" must be \"lower\", \"upper\" or \"set\"")
    };

    private static string? OptionalString(JsonElement element, string name)
    {
        if (!element.TryGetProperty(name, out var value))
        {
            return null;
        }
        return value.ValueKind switch
        {
            JsonValueKind.String => value.GetString(),
            JsonValueKind.Null => null,
            _ => value.ToString()
        };
    }

    private static bool? OptionalBool(JsonElement element, string name)
    {
        if (!element.TryGetProperty(name, out var value))
        {
            return null;
        }
        return value.ValueKind switch
        {
            JsonValueKind.True => true,
            JsonValueKind.False => false,
            _ => null
        };
    }

    private static int? OptionalInt(JsonElement element, string name)
    {
        if (!element.TryGetProperty(name, out var value))
        {
            return null;
        }
        if (value.ValueKind == JsonValueKind.Number && value.TryGetInt32(out int number))
        {
            return number;
        }
        if (value.ValueKind == JsonValueKind.String && int.TryParse(value.GetString(), out int parsed))
        {
            return parsed;
        }
        return null;
    }

    /// <summary>Serialises a rule set back to the contract's rules.json shape (used by the GUI's Save).</summary>
    public static string Serialize(RuleSet rules)
    {
        var buffer = new MemoryStream();
        var options = new JsonWriterOptions
        {
            Indented = true,
            Encoder = JavaScriptEncoder.UnsafeRelaxedJsonEscaping
        };
        using (var writer = new Utf8JsonWriter(buffer, options))
        {
            writer.WriteStartObject();
            writer.WriteString("applyTo", rules.ApplyTo == ApplyTo.Name ? "name" : "nameAndExtension");
            writer.WriteString("sort", rules.Sort.ToString().ToLowerInvariant());
            writer.WriteStartArray("steps");
            foreach (var step in rules.Steps)
            {
                WriteStep(writer, step);
            }
            writer.WriteEndArray();
            writer.WriteEndObject();
        }
        return Utf8NoBom.GetString(buffer.ToArray());
    }

    public static void Save(string path, RuleSet rules)
        => File.WriteAllText(path, Serialize(rules), Utf8NoBom);

    private static void WriteStep(Utf8JsonWriter writer, RuleStep step)
    {
        writer.WriteStartObject();
        writer.WriteString("op", step.Op);
        switch (step)
        {
            case ReplaceStep replace:
                writer.WriteString("find", replace.Find);
                writer.WriteString("replaceWith", replace.ReplaceWith);
                writer.WriteBoolean("regex", replace.Regex);
                writer.WriteBoolean("ignoreCase", replace.IgnoreCase);
                break;
            case InsertStep insert:
                writer.WriteString("text", insert.Text);
                writer.WriteString("position", insert.Position.ToString().ToLowerInvariant());
                writer.WriteNumber("index", insert.Index);
                break;
            case RemoveStep remove:
                writer.WriteNumber("from", remove.From);
                writer.WriteNumber("count", remove.Count);
                break;
            case SequenceStep sequence:
                writer.WriteString("pattern", sequence.Pattern);
                writer.WriteNumber("start", sequence.Start);
                writer.WriteNumber("step", sequence.Step);
                writer.WriteString("position", sequence.Position.ToString().ToLowerInvariant());
                break;
            case CaseStep caseStep:
                writer.WriteString("mode", caseStep.Mode.ToString().ToLowerInvariant());
                break;
            case ExtensionStep extension:
                writer.WriteString("mode", extension.Mode.ToString().ToLowerInvariant());
                writer.WriteString("value", extension.Value);
                break;
        }
        writer.WriteEndObject();
    }
}

