using System.Text;
using System.Text.Encodings.Web;
using System.Text.Json;

namespace BatchRenameStudio.Core;

/// <summary>Writes plan.json exactly as the fixed contract specifies: UTF-8, no BOM, deterministic.</summary>
public static class PlanJson
{
    private static readonly UTF8Encoding Utf8NoBom = new(encoderShouldEmitUTF8Identifier: false);

    public static byte[] SerializeToUtf8(Plan plan)
    {
        var buffer = new MemoryStream();
        var options = new JsonWriterOptions
        {
            Indented = true,
            // Keeps non-ASCII file names readable in the plan; escaping is still fully deterministic.
            Encoder = JavaScriptEncoder.UnsafeRelaxedJsonEscaping,
            SkipValidation = false
        };

        using (var writer = new Utf8JsonWriter(buffer, options))
        {
            writer.WriteStartObject();
            writer.WriteNumber("schemaVersion", plan.SchemaVersion);

            writer.WriteStartArray("items");
            foreach (var item in plan.Items)
            {
                writer.WriteStartObject();
                writer.WriteString("original", item.Original);
                writer.WriteString("proposed", item.Proposed);
                writer.WriteString("status", item.Status);
                writer.WriteString("reason", item.Reason);
                writer.WriteEndObject();
            }
            writer.WriteEndArray();

            writer.WriteStartObject("summary");
            writer.WriteNumber("total", plan.Summary.Total);
            writer.WriteNumber("ok", plan.Summary.Ok);
            writer.WriteNumber("collision", plan.Summary.Collision);
            writer.WriteNumber("unchanged", plan.Summary.Unchanged);
            writer.WriteNumber("invalid", plan.Summary.Invalid);
            writer.WriteEndObject();

            writer.WriteEndObject();
        }

        return buffer.ToArray();
    }

    public static string SerializeToString(Plan plan) => Utf8NoBom.GetString(SerializeToUtf8(plan));

    /// <summary>Writes the plan to disk as UTF-8 without a byte order mark.</summary>
    public static void Write(string path, Plan plan)
    {
        byte[] payload = SerializeToUtf8(plan);
        string? parent = Path.GetDirectoryName(Path.GetFullPath(path));
        if (!string.IsNullOrEmpty(parent))
        {
            Directory.CreateDirectory(parent);
        }
        using var stream = new FileStream(path, FileMode.Create, FileAccess.Write, FileShare.None);
        stream.Write(payload, 0, payload.Length);
        stream.Flush();
    }
}

