namespace BatchRenameStudio.Core;

/// <summary>A single completed rename, kept so it can be reversed.</summary>
public sealed class RenameRecord
{
    public RenameRecord(string from, string to)
    {
        From = from;
        To = to;
    }

    /// <summary>The name the file had before the operation.</summary>
    public string From { get; }

    /// <summary>The name the file has after the operation.</summary>
    public string To { get; }

    public RenameRecord Inverted() => new(To, From);
}

/// <summary>One applied batch: everything needed to undo it in a single step.</summary>
public sealed class RenameBatch
{
    public RenameBatch(string directory, IReadOnlyList<RenameRecord> records)
    {
        Directory = directory;
        Records = records;
    }

    public string Directory { get; }
    public IReadOnlyList<RenameRecord> Records { get; }

    public string Describe() => Records.Count + " file(s) in " + Directory;
}

public sealed class RenameFailure : Exception
{
    public RenameFailure(string message, Exception? inner = null) : base(message, inner)
    {
    }
}

/// <summary>
/// Performs the renames of a plan. Every batch runs in two phases (original -&gt; unique temp name,
/// then temp -&gt; proposed) so that swaps and rotations such as a-&gt;b, b-&gt;a succeed, and so that a
/// failure part-way through can be rolled back to the exact starting state.
/// </summary>
public static class RenameExecutor
{
    private const string TempPrefix = "~brs-";

    /// <summary>Applies every item whose status is "ok". Returns the batch needed to undo it.</summary>
    public static RenameBatch Apply(string directory, IEnumerable<PlanItem> items)
    {
        var pending = items.Where(i => i.IsApplicable).ToList();
        var pairs = pending.Select(i => new RenameRecord(i.Original, i.Proposed)).ToList();
        return Execute(directory, pairs);
    }

    /// <summary>Reverses a previously applied batch.</summary>
    public static RenameBatch Undo(RenameBatch batch)
    {
        var inverted = batch.Records.Select(r => r.Inverted()).ToList();
        return Execute(batch.Directory, inverted);
    }

    private static RenameBatch Execute(string directory, IReadOnlyList<RenameRecord> records)
    {
        if (records.Count == 0)
        {
            return new RenameBatch(directory, Array.Empty<RenameRecord>());
        }

        string token = Guid.NewGuid().ToString("N").Substring(0, 8);
        var staged = new List<(string TempPath, string FinalPath, RenameRecord Record)>(records.Count);

        // Phase 1 - park every source under a name nothing else can want.
        try
        {
            for (int i = 0; i < records.Count; i++)
            {
                var record = records[i];
                string sourcePath = Path.Combine(directory, record.From);
                string tempPath = Path.Combine(directory, TempPrefix + token + "-" + i.ToString("D5") + ".tmp");
                File.Move(sourcePath, tempPath);
                staged.Add((tempPath, Path.Combine(directory, record.To), record));
            }
        }
        catch (Exception ex)
        {
            RollBackPhaseOne(staged, records);
            throw new RenameFailure("rename failed while preparing files; nothing was changed: " + ex.Message, ex);
        }

        // Phase 2 - move each parked file onto its final name.
        int completed = 0;
        try
        {
            for (; completed < staged.Count; completed++)
            {
                File.Move(staged[completed].TempPath, staged[completed].FinalPath);
            }
        }
        catch (Exception ex)
        {
            for (int i = completed - 1; i >= 0; i--)
            {
                TryMove(staged[i].FinalPath, staged[i].TempPath);
            }
            RollBackPhaseOne(staged, records);
            throw new RenameFailure("rename failed part-way through; the folder was restored: " + ex.Message, ex);
        }

        return new RenameBatch(directory, records);
    }

    private static void RollBackPhaseOne(
        List<(string TempPath, string FinalPath, RenameRecord Record)> staged,
        IReadOnlyList<RenameRecord> records)
    {
        for (int i = staged.Count - 1; i >= 0; i--)
        {
            TryMove(staged[i].TempPath, Path.Combine(Path.GetDirectoryName(staged[i].TempPath)!, staged[i].Record.From));
        }
        _ = records;
    }

    private static void TryMove(string from, string to)
    {
        try
        {
            if (File.Exists(from))
            {
                File.Move(from, to);
            }
        }
        catch
        {
            // Best-effort rollback: report the original failure, not the rollback failure.
        }
    }
}

