namespace BatchRenameStudio.Cli;

/// <summary>Minimal "--switch value" parser. Unknown switches are an error, not a silent no-op.</summary>
internal sealed class CommandLine
{
    private readonly Dictionary<string, string?> _values = new(StringComparer.OrdinalIgnoreCase);

    private CommandLine()
    {
    }

    public static CommandLine Parse(string[] args, IReadOnlySet<string> flagSwitches, IReadOnlySet<string> valueSwitches)
    {
        var parsed = new CommandLine();
        for (int i = 0; i < args.Length; i++)
        {
            string arg = args[i];
            if (!arg.StartsWith("--", StringComparison.Ordinal))
            {
                throw new CommandLineException("unexpected argument \"" + arg + "\"");
            }

            string name = arg.Substring(2);
            string? inlineValue = null;
            int equals = name.IndexOf('=');
            if (equals >= 0)
            {
                inlineValue = name.Substring(equals + 1);
                name = name.Substring(0, equals);
            }

            if (flagSwitches.Contains(name))
            {
                parsed._values[name] = inlineValue ?? "true";
                continue;
            }

            if (!valueSwitches.Contains(name))
            {
                throw new CommandLineException("unknown option \"--" + name + "\"");
            }

            if (inlineValue is null)
            {
                if (i + 1 >= args.Length)
                {
                    throw new CommandLineException("option \"--" + name + "\" needs a value");
                }
                inlineValue = args[++i];
            }
            parsed._values[name] = inlineValue;
        }
        return parsed;
    }

    public bool Has(string name) => _values.ContainsKey(name);

    public string Require(string name)
    {
        if (!_values.TryGetValue(name, out string? value) || string.IsNullOrWhiteSpace(value))
        {
            throw new CommandLineException("option \"--" + name + "\" is required");
        }
        return value;
    }

    public string? Optional(string name)
        => _values.TryGetValue(name, out string? value) ? value : null;
}

internal sealed class CommandLineException : Exception
{
    public CommandLineException(string message) : base(message)
    {
    }
}

