using System.ComponentModel;
using BatchRenameStudio.Core;

namespace BatchRenameStudio.Ui;

/// <summary>
/// The whole GUI: pick a folder, stack up rule steps on the left, watch the preview on the right,
/// then apply. The preview is produced by exactly the same planner the headless --plan mode uses,
/// so what a human sees is what the contract produces.
/// </summary>
public sealed class MainForm : Form
{
    private readonly RuleSet _rules = new();
    private readonly List<RuleStep> _steps = new();
    private readonly Stack<RenameBatch> _undoStack = new();

    private readonly TextBox _folderBox = new();
    private readonly ComboBox _applyToBox = new();
    private readonly ComboBox _sortBox = new();
    private readonly CheckedListBox _stepList = new();
    private readonly DataGridView _preview = new();
    private readonly Label _summaryLabel = new();
    private readonly Button _applyButton = new();
    private readonly Button _undoButton = new();
    private readonly StatusStrip _statusStrip = new();
    private readonly ToolStripStatusLabel _statusLabel = new();

    private List<FileEntry> _files = new();
    private Plan? _plan;
    private bool _suspendRefresh;

    public MainForm(string? initialFolder = null)
    {
        Text = "Batch Rename Studio";
        MinimumSize = new Size(940, 560);
        Size = new Size(1180, 700);
        StartPosition = FormStartPosition.CenterScreen;
        AllowDrop = true;

        BuildLayout();
        WireEvents();

        if (!string.IsNullOrWhiteSpace(initialFolder) && Directory.Exists(initialFolder))
        {
            _folderBox.Text = Path.GetFullPath(initialFolder);
            LoadFolder();
        }
        else
        {
            SetStatus("Pick a folder to begin, or drop one onto this window.");
        }
    }

    // ---------------------------------------------------------------- layout

    private void BuildLayout()
    {
        var root = new TableLayoutPanel
        {
            Dock = DockStyle.Fill,
            ColumnCount = 1,
            RowCount = 3,
            Padding = new Padding(10, 10, 10, 0)
        };
        root.RowStyles.Add(new RowStyle(SizeType.AutoSize));
        root.RowStyles.Add(new RowStyle(SizeType.Percent, 100f));
        root.RowStyles.Add(new RowStyle(SizeType.AutoSize));

        root.Controls.Add(BuildHeader(), 0, 0);
        root.Controls.Add(BuildBody(), 0, 1);
        root.Controls.Add(BuildFooter(), 0, 2);

        _statusLabel.Spring = true;
        _statusLabel.TextAlign = ContentAlignment.MiddleLeft;
        _statusStrip.Items.Add(_statusLabel);

        Controls.Add(root);
        Controls.Add(_statusStrip);
    }

    private Control BuildHeader()
    {
        var header = new TableLayoutPanel
        {
            Dock = DockStyle.Top,
            AutoSize = true,
            ColumnCount = 8,
            RowCount = 2
        };
        header.ColumnStyles.Add(new ColumnStyle(SizeType.AutoSize));
        header.ColumnStyles.Add(new ColumnStyle(SizeType.Percent, 100f));
        for (int i = 0; i < 6; i++)
        {
            header.ColumnStyles.Add(new ColumnStyle(SizeType.AutoSize));
        }

        header.Controls.Add(NewLabel("Folder:"), 0, 0);

        _folderBox.Dock = DockStyle.Fill;
        _folderBox.PlaceholderText = @"e.g. D:\Photos\2026-08";
        header.Controls.Add(_folderBox, 1, 0);

        var browse = NewButton("Browse...", 96);
        browse.Click += (_, _) => BrowseForFolder();
        header.Controls.Add(browse, 2, 0);

        var reload = NewButton("Reload", 80);
        reload.Click += (_, _) => LoadFolder();
        header.Controls.Add(reload, 3, 0);

        var optionRow = new FlowLayoutPanel
        {
            AutoSize = true,
            FlowDirection = FlowDirection.LeftToRight,
            Margin = new Padding(0, 6, 0, 6),
            WrapContents = false
        };

        optionRow.Controls.Add(NewLabel("Apply to:"));
        _applyToBox.DropDownStyle = ComboBoxStyle.DropDownList;
        _applyToBox.Width = 190;
        _applyToBox.Items.AddRange(new object[] { "name (base only)", "nameAndExtension" });
        _applyToBox.SelectedIndex = 0;
        optionRow.Controls.Add(_applyToBox);

        optionRow.Controls.Add(NewLabel("      Process order:"));
        _sortBox.DropDownStyle = ComboBoxStyle.DropDownList;
        _sortBox.Width = 150;
        _sortBox.Items.AddRange(new object[] { "name", "created", "modified" });
        _sortBox.SelectedIndex = 0;
        optionRow.Controls.Add(_sortBox);

        var loadRules = NewButton("Load rules...", 110);
        loadRules.Margin = new Padding(24, 0, 3, 0);
        loadRules.Click += (_, _) => LoadRules();
        optionRow.Controls.Add(loadRules);

        var saveRules = NewButton("Save rules...", 110);
        saveRules.Click += (_, _) => SaveRules();
        optionRow.Controls.Add(saveRules);

        var exportPlan = NewButton("Export plan.json...", 150);
        exportPlan.Click += (_, _) => ExportPlan();
        optionRow.Controls.Add(exportPlan);

        header.Controls.Add(optionRow, 0, 1);
        header.SetColumnSpan(optionRow, 8);
        return header;
    }

    private Control BuildBody()
    {
        var split = new SplitContainer
        {
            Dock = DockStyle.Fill,
            Orientation = Orientation.Vertical,
            SplitterDistance = 400,
            SplitterWidth = 8
        };

        var rulesBox = new GroupBox { Text = "Rule steps (applied top to bottom)", Dock = DockStyle.Fill, Padding = new Padding(8) };

        _stepList.Dock = DockStyle.Fill;
        _stepList.CheckOnClick = true;
        _stepList.IntegralHeight = false;

        var stepButtons = new FlowLayoutPanel
        {
            Dock = DockStyle.Bottom,
            AutoSize = true,
            FlowDirection = FlowDirection.LeftToRight,
            WrapContents = true
        };

        var add = NewButton("Add step", 90);
        add.Click += (_, _) => ShowAddMenu(add);
        stepButtons.Controls.Add(add);

        var edit = NewButton("Edit", 70);
        edit.Click += (_, _) => EditSelectedStep();
        stepButtons.Controls.Add(edit);

        var remove = NewButton("Remove", 80);
        remove.Click += (_, _) => RemoveSelectedStep();
        stepButtons.Controls.Add(remove);

        var up = NewButton("Up", 55);
        up.Click += (_, _) => MoveSelectedStep(-1);
        stepButtons.Controls.Add(up);

        var down = NewButton("Down", 62);
        down.Click += (_, _) => MoveSelectedStep(1);
        stepButtons.Controls.Add(down);

        var clear = NewButton("Clear", 68);
        clear.Click += (_, _) => ClearSteps();
        stepButtons.Controls.Add(clear);

        var hint = new Label
        {
            Dock = DockStyle.Bottom,
            AutoSize = false,
            Height = 34,
            ForeColor = SystemColors.GrayText,
            Text = "Uncheck a step to disable it without deleting it. Double-click a step to edit."
        };

        rulesBox.Controls.Add(_stepList);
        rulesBox.Controls.Add(hint);
        rulesBox.Controls.Add(stepButtons);

        var previewBox = new GroupBox { Text = "Preview", Dock = DockStyle.Fill, Padding = new Padding(8) };

        _preview.Dock = DockStyle.Fill;
        _preview.ReadOnly = true;
        _preview.AllowUserToAddRows = false;
        _preview.AllowUserToDeleteRows = false;
        _preview.AllowUserToResizeRows = false;
        _preview.RowHeadersVisible = false;
        _preview.SelectionMode = DataGridViewSelectionMode.FullRowSelect;
        _preview.AutoSizeColumnsMode = DataGridViewAutoSizeColumnsMode.Fill;
        _preview.EnableHeadersVisualStyles = false;
        _preview.Columns.Add(NewColumn("original", "Original", 34));
        _preview.Columns.Add(NewColumn("proposed", "Proposed", 34));
        _preview.Columns.Add(NewColumn("status", "Status", 12));
        _preview.Columns.Add(NewColumn("reason", "Reason", 20));

        _summaryLabel.Dock = DockStyle.Bottom;
        _summaryLabel.Height = 24;
        _summaryLabel.TextAlign = ContentAlignment.MiddleLeft;
        _summaryLabel.Text = "total=0 ok=0 collision=0 unchanged=0 invalid=0";

        previewBox.Controls.Add(_preview);
        previewBox.Controls.Add(_summaryLabel);

        split.Panel1.Controls.Add(rulesBox);
        split.Panel2.Controls.Add(previewBox);
        return split;
    }

    private Control BuildFooter()
    {
        var footer = new FlowLayoutPanel
        {
            Dock = DockStyle.Bottom,
            AutoSize = true,
            FlowDirection = FlowDirection.RightToLeft,
            Padding = new Padding(0, 6, 0, 6)
        };

        _applyButton.Text = "Apply rename";
        _applyButton.Width = 140;
        _applyButton.Height = 32;
        _applyButton.Enabled = false;
        footer.Controls.Add(_applyButton);

        _undoButton.Text = "Undo last";
        _undoButton.Width = 110;
        _undoButton.Height = 32;
        _undoButton.Enabled = false;
        footer.Controls.Add(_undoButton);

        return footer;
    }

    private static DataGridViewTextBoxColumn NewColumn(string name, string header, int fillWeight)
        => new() { Name = name, HeaderText = header, FillWeight = fillWeight, SortMode = DataGridViewColumnSortMode.NotSortable };

    private static Label NewLabel(string text)
        => new() { Text = text, AutoSize = true, Margin = new Padding(3, 7, 3, 3) };

    private static Button NewButton(string text, int width)
        => new() { Text = text, Width = width, Height = 26, Margin = new Padding(3) };

    // ---------------------------------------------------------------- events

    private void WireEvents()
    {
        _applyToBox.SelectedIndexChanged += (_, _) => RefreshPreview();
        _sortBox.SelectedIndexChanged += (_, _) => RefreshPreview();
        _stepList.ItemCheck += (_, _) => BeginInvoke(new Action(RefreshPreview));
        _stepList.DoubleClick += (_, _) => EditSelectedStep();
        _folderBox.KeyDown += (_, e) =>
        {
            if (e.KeyCode == Keys.Enter)
            {
                e.SuppressKeyPress = true;
                LoadFolder();
            }
        };
        _applyButton.Click += (_, _) => ApplyRename();
        _undoButton.Click += (_, _) => UndoLast();
        _preview.CellFormatting += FormatPreviewCell;

        DragEnter += (_, e) =>
        {
            if (e.Data?.GetDataPresent(DataFormats.FileDrop) == true)
            {
                e.Effect = DragDropEffects.Copy;
            }
        };
        DragDrop += (_, e) =>
        {
            if (e.Data?.GetData(DataFormats.FileDrop) is string[] { Length: > 0 } paths)
            {
                string candidate = Directory.Exists(paths[0]) ? paths[0] : Path.GetDirectoryName(paths[0]) ?? string.Empty;
                if (Directory.Exists(candidate))
                {
                    _folderBox.Text = candidate;
                    LoadFolder();
                }
            }
        };
    }

    private void FormatPreviewCell(object? sender, DataGridViewCellFormattingEventArgs e)
    {
        if (e.RowIndex < 0 || e.RowIndex >= _preview.Rows.Count)
        {
            return;
        }
        if (_preview.Rows[e.RowIndex].Tag is not string status)
        {
            return;
        }
        var row = _preview.Rows[e.RowIndex];
        row.DefaultCellStyle.BackColor = status switch
        {
            PlanStatus.Ok => Color.FromArgb(236, 250, 238),
            PlanStatus.Collision => Color.FromArgb(255, 238, 232),
            PlanStatus.Invalid => Color.FromArgb(255, 230, 230),
            _ => Color.FromArgb(246, 246, 246)
        };
        row.DefaultCellStyle.ForeColor = status == PlanStatus.Unchanged ? SystemColors.GrayText : SystemColors.ControlText;
    }

    // ---------------------------------------------------------------- folder

    private void BrowseForFolder()
    {
        using var dialog = new FolderBrowserDialog { Description = "Choose the folder to rename in", UseDescriptionForTitle = true };
        if (Directory.Exists(_folderBox.Text))
        {
            dialog.SelectedPath = _folderBox.Text;
        }
        if (dialog.ShowDialog(this) == DialogResult.OK)
        {
            _folderBox.Text = dialog.SelectedPath;
            LoadFolder();
        }
    }

    private void LoadFolder()
    {
        string folder = _folderBox.Text.Trim().Trim('"');
        if (!Directory.Exists(folder))
        {
            _files = new List<FileEntry>();
            _plan = null;
            _preview.Rows.Clear();
            _applyButton.Enabled = false;
            SetStatus(folder.Length == 0 ? "No folder selected." : "Folder not found: " + folder);
            return;
        }

        try
        {
            _files = RenamePlanner.ReadFolder(folder);
            _undoStack.Clear();
            _undoButton.Enabled = false;
            SetStatus(_files.Count + " file(s) in " + folder);
            RefreshPreview();
        }
        catch (Exception ex) when (ex is IOException or UnauthorizedAccessException)
        {
            SetStatus("Cannot read folder: " + ex.Message);
        }
    }

    // ---------------------------------------------------------------- rules

    private RuleSet CurrentRules()
    {
        _rules.ApplyTo = _applyToBox.SelectedIndex == 1 ? ApplyTo.NameAndExtension : ApplyTo.Name;
        _rules.Sort = _sortBox.SelectedIndex switch
        {
            1 => SortMode.Created,
            2 => SortMode.Modified,
            _ => SortMode.Name
        };
        _rules.Steps.Clear();
        for (int i = 0; i < _steps.Count; i++)
        {
            if (_stepList.GetItemChecked(i))
            {
                _rules.Steps.Add(_steps[i]);
            }
        }
        return _rules;
    }

    private void RebuildStepList(int selectedIndex = -1)
    {
        _suspendRefresh = true;
        var checkedFlags = new List<bool>();
        for (int i = 0; i < _stepList.Items.Count; i++)
        {
            checkedFlags.Add(_stepList.GetItemChecked(i));
        }

        _stepList.Items.Clear();
        for (int i = 0; i < _steps.Count; i++)
        {
            bool isChecked = i < checkedFlags.Count ? checkedFlags[i] : true;
            _stepList.Items.Add(_steps[i].Describe(), isChecked);
        }
        if (selectedIndex >= 0 && selectedIndex < _stepList.Items.Count)
        {
            _stepList.SelectedIndex = selectedIndex;
        }
        _suspendRefresh = false;
        RefreshPreview();
    }

    private void ShowAddMenu(Control anchor)
    {
        var menu = new ContextMenuStrip();
        AddMenuEntry(menu, "Replace text...", () => new ReplaceStep { Find = string.Empty, ReplaceWith = string.Empty });
        AddMenuEntry(menu, "Insert text...", () => new InsertStep { Text = string.Empty, Position = InsertPosition.Prefix });
        AddMenuEntry(menu, "Remove characters...", () => new RemoveStep { From = 0, Count = 1 });
        AddMenuEntry(menu, "Numbering sequence...", () => new SequenceStep());
        AddMenuEntry(menu, "Change case...", () => new CaseStep());
        AddMenuEntry(menu, "Extension...", () => new ExtensionStep());
        menu.Show(anchor, new Point(0, anchor.Height));
    }

    private void AddMenuEntry(ContextMenuStrip menu, string text, Func<RuleStep> factory)
    {
        menu.Items.Add(text, null, (_, _) =>
        {
            var step = factory();
            using var editor = new StepEditorForm(step);
            if (editor.ShowDialog(this) == DialogResult.OK)
            {
                _steps.Add(editor.Result);
                _stepList.Items.Add(editor.Result.Describe(), true);
                _stepList.SelectedIndex = _stepList.Items.Count - 1;
                RefreshPreview();
            }
        });
    }

    private void EditSelectedStep()
    {
        int index = _stepList.SelectedIndex;
        if (index < 0 || index >= _steps.Count)
        {
            return;
        }
        using var editor = new StepEditorForm(_steps[index]);
        if (editor.ShowDialog(this) == DialogResult.OK)
        {
            _steps[index] = editor.Result;
            _stepList.Items[index] = editor.Result.Describe();
            RefreshPreview();
        }
    }

    private void RemoveSelectedStep()
    {
        int index = _stepList.SelectedIndex;
        if (index < 0 || index >= _steps.Count)
        {
            return;
        }
        _steps.RemoveAt(index);
        _suspendRefresh = true;
        _stepList.Items.RemoveAt(index);
        _suspendRefresh = false;
        if (_stepList.Items.Count > 0)
        {
            _stepList.SelectedIndex = Math.Min(index, _stepList.Items.Count - 1);
        }
        RefreshPreview();
    }

    private void MoveSelectedStep(int delta)
    {
        int index = _stepList.SelectedIndex;
        int target = index + delta;
        if (index < 0 || target < 0 || target >= _steps.Count)
        {
            return;
        }
        (_steps[index], _steps[target]) = (_steps[target], _steps[index]);

        _suspendRefresh = true;
        bool a = _stepList.GetItemChecked(index);
        bool b = _stepList.GetItemChecked(target);
        _stepList.Items[index] = _steps[index].Describe();
        _stepList.Items[target] = _steps[target].Describe();
        _stepList.SetItemChecked(index, b);
        _stepList.SetItemChecked(target, a);
        _stepList.SelectedIndex = target;
        _suspendRefresh = false;
        RefreshPreview();
    }

    private void ClearSteps()
    {
        if (_steps.Count == 0)
        {
            return;
        }
        if (MessageBox.Show(this, "Remove all rule steps?", "Batch Rename Studio",
                MessageBoxButtons.YesNo, MessageBoxIcon.Question) != DialogResult.Yes)
        {
            return;
        }
        _steps.Clear();
        _suspendRefresh = true;
        _stepList.Items.Clear();
        _suspendRefresh = false;
        RefreshPreview();
    }

    private void LoadRules()
    {
        using var dialog = new OpenFileDialog
        {
            Title = "Load rules.json",
            Filter = "Rule sets (*.json)|*.json|All files (*.*)|*.*"
        };
        if (dialog.ShowDialog(this) != DialogResult.OK)
        {
            return;
        }
        try
        {
            var loaded = RulesJson.Load(dialog.FileName);
            _applyToBox.SelectedIndex = loaded.ApplyTo == ApplyTo.NameAndExtension ? 1 : 0;
            _sortBox.SelectedIndex = loaded.Sort switch
            {
                SortMode.Created => 1,
                SortMode.Modified => 2,
                _ => 0
            };
            _steps.Clear();
            _steps.AddRange(loaded.Steps.Select(s => s.Clone()));
            _suspendRefresh = true;
            _stepList.Items.Clear();
            foreach (var step in _steps)
            {
                _stepList.Items.Add(step.Describe(), true);
            }
            _suspendRefresh = false;
            RefreshPreview();
            SetStatus("Loaded rules from " + dialog.FileName);
        }
        catch (RuleException ex)
        {
            MessageBox.Show(this, ex.Message, "Cannot load rules", MessageBoxButtons.OK, MessageBoxIcon.Warning);
        }
    }

    private void SaveRules()
    {
        using var dialog = new SaveFileDialog
        {
            Title = "Save rules.json",
            Filter = "Rule sets (*.json)|*.json",
            FileName = "rules.json"
        };
        if (dialog.ShowDialog(this) != DialogResult.OK)
        {
            return;
        }
        try
        {
            RulesJson.Save(dialog.FileName, CurrentRules());
            SetStatus("Saved rules to " + dialog.FileName);
        }
        catch (Exception ex) when (ex is IOException or UnauthorizedAccessException)
        {
            MessageBox.Show(this, ex.Message, "Cannot save rules", MessageBoxButtons.OK, MessageBoxIcon.Warning);
        }
    }

    private void ExportPlan()
    {
        if (_plan is null)
        {
            MessageBox.Show(this, "There is no preview to export yet.", "Batch Rename Studio",
                MessageBoxButtons.OK, MessageBoxIcon.Information);
            return;
        }
        using var dialog = new SaveFileDialog
        {
            Title = "Export plan.json",
            Filter = "Plans (*.json)|*.json",
            FileName = "plan.json"
        };
        if (dialog.ShowDialog(this) != DialogResult.OK)
        {
            return;
        }
        try
        {
            PlanJson.Write(dialog.FileName, _plan);
            SetStatus("Exported plan to " + dialog.FileName);
        }
        catch (Exception ex) when (ex is IOException or UnauthorizedAccessException)
        {
            MessageBox.Show(this, ex.Message, "Cannot export plan", MessageBoxButtons.OK, MessageBoxIcon.Warning);
        }
    }

    // ---------------------------------------------------------------- preview

    private void RefreshPreview()
    {
        if (_suspendRefresh)
        {
            return;
        }

        _preview.Rows.Clear();
        if (_files.Count == 0)
        {
            _plan = null;
            _summaryLabel.Text = "total=0 ok=0 collision=0 unchanged=0 invalid=0";
            _applyButton.Enabled = false;
            return;
        }

        try
        {
            _plan = RenamePlanner.Create(_files, CurrentRules());
        }
        catch (RuleException ex)
        {
            _plan = null;
            _summaryLabel.Text = "Rule error: " + ex.Message;
            _applyButton.Enabled = false;
            return;
        }

        _preview.SuspendLayout();
        foreach (var item in _plan.Items)
        {
            int index = _preview.Rows.Add(item.Original, item.Proposed, item.Status, item.Reason);
            _preview.Rows[index].Tag = item.Status;
        }
        _preview.ResumeLayout();

        _summaryLabel.Text = _plan.Summary.ToString();
        _applyButton.Enabled = _plan.Summary.Ok > 0;
        _applyButton.Text = _plan.Summary.Ok > 0 ? "Apply rename (" + _plan.Summary.Ok + ")" : "Apply rename";
    }

    // ---------------------------------------------------------------- apply / undo

    private void ApplyRename()
    {
        string folder = _folderBox.Text.Trim().Trim('"');
        if (!Directory.Exists(folder) || _plan is null)
        {
            return;
        }

        // Re-read the folder so the plan we execute reflects the disk as it is right now.
        _files = RenamePlanner.ReadFolder(folder);
        RefreshPreview();
        if (_plan is null || _plan.Summary.Ok == 0)
        {
            SetStatus("Nothing to rename.");
            return;
        }

        var confirm = MessageBox.Show(
            this,
            "Rename " + _plan.Summary.Ok + " file(s) in:\n" + folder +
            "\n\nSkipped: " + _plan.Summary.Collision + " collision, " +
            _plan.Summary.Invalid + " invalid, " + _plan.Summary.Unchanged + " unchanged.",
            "Confirm rename",
            MessageBoxButtons.OKCancel,
            MessageBoxIcon.Question);
        if (confirm != DialogResult.OK)
        {
            return;
        }

        try
        {
            Cursor = Cursors.WaitCursor;
            var batch = RenameExecutor.Apply(folder, _plan.Items);
            _undoStack.Push(batch);
            _undoButton.Enabled = true;
            SetStatus("Renamed " + batch.Records.Count + " file(s).");
        }
        catch (RenameFailure ex)
        {
            MessageBox.Show(this, ex.Message, "Rename failed", MessageBoxButtons.OK, MessageBoxIcon.Error);
            SetStatus("Rename failed: " + ex.Message);
        }
        finally
        {
            Cursor = Cursors.Default;
            _files = RenamePlanner.ReadFolder(folder);
            RefreshPreview();
        }
    }

    private void UndoLast()
    {
        if (_undoStack.Count == 0)
        {
            return;
        }
        var batch = _undoStack.Peek();
        try
        {
            Cursor = Cursors.WaitCursor;
            RenameExecutor.Undo(batch);
            _undoStack.Pop();
            SetStatus("Undid " + batch.Describe() + ".");
        }
        catch (RenameFailure ex)
        {
            MessageBox.Show(this, ex.Message, "Undo failed", MessageBoxButtons.OK, MessageBoxIcon.Error);
        }
        finally
        {
            Cursor = Cursors.Default;
            _undoButton.Enabled = _undoStack.Count > 0;
            if (Directory.Exists(batch.Directory))
            {
                _files = RenamePlanner.ReadFolder(batch.Directory);
            }
            RefreshPreview();
        }
    }

    private void SetStatus(string text) => _statusLabel.Text = text;

    protected override void OnFormClosing(FormClosingEventArgs e)
    {
        base.OnFormClosing(e);
        _ = (CancelEventArgs)e;
    }
}

