using System.Runtime.InteropServices;
using System.Text;

namespace BatchRenameStudio.Cli;

/// <summary>
/// The executable is a WinExe (it owns a GUI), so it has no console of its own. When it is invoked
/// with headless switches we either use the caller's redirected pipe/file handles as-is, or attach
/// to the parent console so a human running it from cmd/PowerShell still sees the summary line.
/// </summary>
internal static class ConsoleBridge
{
    private const int StdOutputHandle = -11;
    private const int StdErrorHandle = -12;
    private const uint AttachParentProcess = 0xFFFFFFFF;

    private static bool _attached;

    [DllImport("kernel32.dll", SetLastError = true)]
    private static extern bool AttachConsole(uint dwProcessId);

    [DllImport("kernel32.dll", SetLastError = true)]
    private static extern IntPtr GetStdHandle(int nStdHandle);

    /// <summary>Makes Console.Out / Console.Error usable. Safe to call more than once.</summary>
    public static void Ensure()
    {
        if (_attached)
        {
            return;
        }
        _attached = true;

        bool hasStdOut = IsUsable(GetStdHandle(StdOutputHandle));
        bool hasStdErr = IsUsable(GetStdHandle(StdErrorHandle));

        // Handles already exist (the caller redirected them, or cmd passed its console through):
        // leave them alone so redirection to a file or pipe keeps working byte for byte.
        if (hasStdOut && hasStdErr)
        {
            return;
        }

        if (AttachConsole(AttachParentProcess))
        {
            if (!hasStdOut)
            {
                Console.SetOut(new StreamWriter(Console.OpenStandardOutput(), new UTF8Encoding(false)) { AutoFlush = true });
            }
            if (!hasStdErr)
            {
                Console.SetError(new StreamWriter(Console.OpenStandardError(), new UTF8Encoding(false)) { AutoFlush = true });
            }
        }
    }

    private static bool IsUsable(IntPtr handle)
        => handle != IntPtr.Zero && handle != new IntPtr(-1);
}

