using BatchRenameStudio.Core;

namespace BatchRenameStudio.Ui;

/// <summary>
/// Modal editor for a single rule step. It always edits a CLONE, so pressing Cancel leaves the
/// caller's rule set untouched; <see cref="Result"/> is only meaningful after DialogResult.OK.
/// </summary>
public sealed class StepEditorForm : Form
{
    private readonly RuleStep _draft;
    private readonly TableLayoutPanel _fields = new();
    private readonly List<Func<string?>> _validators = new();
    private readonly List<Action> _committers = new();

    public StepEditorForm(RuleStep step)
    {
        _draft = step.Clone();
        Result = _draft;

        Text = "Step: " + _draft.Op;
        FormBorderStyle = FormBorderStyle.FixedDialog;
        MinimizeBox = false;
        MaximizeBox = false;
        StartPosition = FormStartPosition.CenterParent;
        ClientSize = new Size(460, 220);
        Padding = new Padding(12);

        _fields.Dock = DockStyle.Fill;
        _fields.ColumnCount = 2;
        _fields.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute, 130f));
        _fields.ColumnStyles.Add(new ColumnStyle(SizeType.Percent, 100f));
        _fields.AutoSize = true;

        BuildFields();

        var buttons = new FlowLayoutPanel
        {
            Dock = DockStyle.Bottom,
            FlowDirection = FlowDirection.RightToLeft,
            AutoSize = true,
            Padding = new Padding(0, 8, 0, 0)
        };

        var ok = new Button { Text = "OK", DialogResult = DialogResult.None, Width = 90, Height = 28 };
        var cancel = new Button { Text = "Cancel", DialogResult = DialogResult.Cancel, Width = 90, Height = 28 };
        ok.Click += (_, _) => Commit();
        buttons.Controls.Add(ok);
        buttons.Controls.Add(cancel);

        AcceptButton = ok;
        CancelButton = cancel;

        Controls.Add(_fields);
        Controls.Add(buttons);
    }

    /// <summary>The edited step. Only valid when the dialog returned <see cref="DialogResult.OK"/>.</summary>
    public RuleStep Result { get; private set; }

    private void Commit()
    {
        foreach (var validator in _validators)
        {
            string? error = validator();
            if (error is not null)
            {
                MessageBox.Show(this, error, "Invalid value", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                return;
            }
        }
        foreach (var commit in _committers)
        {
            commit();
        }
        Result = _draft;
        DialogResult = DialogResult.OK;
        Close();
    }

    private void BuildFields()
    {
        switch (_draft)
        {
            case ReplaceStep replace:
                BuildReplace(replace);
                break;
            case InsertStep insert:
                BuildInsert(insert);
                break;
            case RemoveStep remove:
                BuildRemove(remove);
                break;
            case SequenceStep sequence:
                BuildSequence(sequence);
                break;
            case CaseStep caseStep:
                BuildCase(caseStep);
                break;
            case ExtensionStep extension:
                BuildExtension(extension);
                break;
        }
        AddHint(HintFor(_draft));
    }

    private static string HintFor(RuleStep step) => step switch
    {
        ReplaceStep => "Every occurrence is replaced. In regex mode the replacement may use $1, $2 ... group references.",
        InsertStep => "\"index\" is 0-based and clamped into the target string.",
        RemoveStep => "\"from\" is 0-based; both values are clamped, so an over-long range simply removes what is left.",
        SequenceStep => "The pattern holds literal text plus one {n:000} token; the zero count sets the padding width. The counter advances for every file, even skipped ones.",
        CaseStep => "\"title\" upper-cases the first letter of each run of letters and lower-cases the rest.",
        ExtensionStep => "This step always targets the extension, whatever \"apply to\" is set to. \"set\" takes a value with no leading dot.",
        _ => string.Empty
    };

    // ---------------------------------------------------------------- per-op fields

    private void BuildReplace(ReplaceStep step)
    {
        var find = AddTextBox("Find:", step.Find);
        var replaceWith = AddTextBox("Replace with:", step.ReplaceWith);
        var regex = AddCheckBox("Regular expression", step.Regex);
        var ignoreCase = AddCheckBox("Ignore case", step.IgnoreCase);

        _validators.Add(() =>
        {
            if (!regex.Checked)
            {
                return null;
            }
            try
            {
                _ = new System.Text.RegularExpressions.Regex(find.Text);
                return null;
            }
            catch (ArgumentException ex)
            {
                return "That regular expression does not compile:\n\n" + ex.Message;
            }
        });

        _committers.Add(() =>
        {
            step.Find = find.Text;
            step.ReplaceWith = replaceWith.Text;
            step.Regex = regex.Checked;
            step.IgnoreCase = ignoreCase.Checked;
            step.Invalidate();
        });
    }

    private void BuildInsert(InsertStep step)
    {
        var text = AddTextBox("Text:", step.Text);
        var position = AddCombo("Position:", new[] { "prefix", "suffix", "index" }, (int)step.Position);
        var index = AddNumeric("Index:", step.Index, 0, 4096);

        position.SelectedIndexChanged += (_, _) => index.Enabled = position.SelectedIndex == 2;
        index.Enabled = position.SelectedIndex == 2;

        _committers.Add(() =>
        {
            step.Text = text.Text;
            step.Position = (InsertPosition)position.SelectedIndex;
            step.Index = (int)index.Value;
        });
    }

    private void BuildRemove(RemoveStep step)
    {
        var from = AddNumeric("From index:", step.From, 0, 4096);
        var count = AddNumeric("Count:", step.Count, 0, 4096);
        _committers.Add(() =>
        {
            step.From = (int)from.Value;
            step.Count = (int)count.Value;
        });
    }

    private void BuildSequence(SequenceStep step)
    {
        var pattern = AddTextBox("Pattern:", step.Pattern);
        var start = AddNumeric("Start:", step.Start, -1_000_000, 1_000_000);
        var increment = AddNumeric("Step:", step.Step, -1_000_000, 1_000_000);
        var position = AddCombo("Position:", new[] { "prefix", "suffix" }, (int)step.Position);

        _committers.Add(() =>
        {
            step.Pattern = pattern.Text;
            step.Start = (int)start.Value;
            step.Step = (int)increment.Value;
            step.Position = (AffixPosition)position.SelectedIndex;
        });
    }

    private void BuildCase(CaseStep step)
    {
        var mode = AddCombo("Mode:", new[] { "upper", "lower", "title" }, (int)step.Mode);
        _committers.Add(() => step.Mode = (CaseMode)mode.SelectedIndex);
    }

    private void BuildExtension(ExtensionStep step)
    {
        var mode = AddCombo("Mode:", new[] { "lower", "upper", "set" }, (int)step.Mode);
        var value = AddTextBox("Value:", step.Value);

        void SyncValueState() => value.Enabled = mode.SelectedIndex == 2;
        mode.SelectedIndexChanged += (_, _) => SyncValueState();
        SyncValueState();

        _committers.Add(() =>
        {
            step.Mode = (ExtensionMode)mode.SelectedIndex;
            step.Value = value.Text.TrimStart('.');
        });
    }

    // ---------------------------------------------------------------- field helpers

    private TextBox AddTextBox(string label, string value)
    {
        var box = new TextBox { Text = value, Dock = DockStyle.Fill, Margin = new Padding(3, 4, 3, 4) };
        AddRow(label, box);
        return box;
    }

    private CheckBox AddCheckBox(string label, bool value)
    {
        var box = new CheckBox { Text = label, Checked = value, AutoSize = true, Margin = new Padding(3, 4, 3, 4) };
        AddRow(string.Empty, box);
        return box;
    }

    private ComboBox AddCombo(string label, string[] values, int selected)
    {
        var box = new ComboBox { DropDownStyle = ComboBoxStyle.DropDownList, Dock = DockStyle.Fill, Margin = new Padding(3, 4, 3, 4) };
        box.Items.AddRange(values);
        box.SelectedIndex = Math.Max(0, Math.Min(selected, values.Length - 1));
        AddRow(label, box);
        return box;
    }

    private NumericUpDown AddNumeric(string label, int value, int min, int max)
    {
        var box = new NumericUpDown
        {
            Minimum = min,
            Maximum = max,
            Value = Math.Max(min, Math.Min(max, value)),
            Dock = DockStyle.Fill,
            Margin = new Padding(3, 4, 3, 4)
        };
        AddRow(label, box);
        return box;
    }

    private void AddHint(string text)
    {
        if (text.Length == 0)
        {
            return;
        }
        var hint = new Label
        {
            Text = text,
            ForeColor = SystemColors.GrayText,
            Dock = DockStyle.Fill,
            AutoSize = true,
            Margin = new Padding(3, 10, 3, 3),
            MaximumSize = new Size(420, 0)
        };
        int row = _fields.RowCount++;
        _fields.Controls.Add(hint, 0, row);
        _fields.SetColumnSpan(hint, 2);
    }

    private void AddRow(string label, Control control)
    {
        int row = _fields.RowCount++;
        if (label.Length > 0)
        {
            _fields.Controls.Add(new Label { Text = label, AutoSize = true, Margin = new Padding(3, 8, 3, 3) }, 0, row);
            _fields.Controls.Add(control, 1, row);
        }
        else
        {
            _fields.Controls.Add(control, 1, row);
        }
    }
}

