using BatchRenameStudio.Core;

namespace BatchRenameStudio.Cli;

/// <summary>
/// Executable specification for the 16 numbered semantics of the fixed contract.
/// It runs entirely on synthetic <see cref="FileEntry"/> values, so it needs no test framework,
/// no NuGet package and no filesystem. "BatchRenameStudio.exe --selftest" exits 0 when all pass.
/// </summary>
internal static class SelfTest
{
    private static int _passed;
    private static readonly List<string> Failures = new();

    public static int Run()
    {
        ConsoleBridge.Ensure();
        _passed = 0;
        Failures.Clear();

        NameSplitRules();
        StepRules();
        SequenceRules();
        StatusRules();
        OrderingRules();
        DeterminismRules();

        foreach (string failure in Failures)
        {
            Console.Error.WriteLine("FAIL " + failure);
        }
        Console.Out.WriteLine("selftest: " + _passed + " passed, " + Failures.Count + " failed");
        return Failures.Count == 0 ? HeadlessRunner.ExitSuccess : 1;
    }

    // ------------------------------------------------------------------ rule 2, 12

    private static void NameSplitRules()
    {
        CheckSplit("a.txt", "a", "txt");
        CheckSplit(".gitignore", ".gitignore", "");
        CheckSplit("README", "README", "");
        CheckSplit("dots.tar.gz", "dots.tar", "gz");
        CheckSplit("trailing.", "trailing", "");
        CheckSplit(".", ".", "");

        Check("join with ext", NameUtil.Join("a", "txt") == "a.txt");
        Check("join without ext", NameUtil.Join("a", "") == "a");
    }

