    private static void OrderingRules()
    {
        var files = new[]
        {
            new FileEntry("b.txt", new DateTime(2020, 1, 3), new DateTime(2020, 1, 1)),
            new FileEntry("A.txt", new DateTime(2020, 1, 2), new DateTime(2020, 1, 2)),
