        var files = new[] { Entry("b.txt"), Entry("a.txt"), Entry("C.md") };
        var rules = RulesJson.Parse("""
            {
              "applyTo": "nameAndExtension",
              "sort": "name",
              "steps": [
                {"op":"sequence","pattern":"{n:00}_","start":1,"step":1,"position":"prefix"},
                {"op":"case","mode":"upper"},
                {"op":"extension","mode":"lower"}
              ]
            }
            """);

        string first = PlanJson.SerializeToString(RenamePlanner.Create(files, rules));
        string second = PlanJson.SerializeToString(RenamePlanner.Create(files.Reverse().ToArray(), rules));
        Check("rule 15 identical inputs give identical bytes", first == second);

        byte[] bytes = PlanJson.SerializeToUtf8(RenamePlanner.Create(files, rules));
