        Check("plan.json declares schemaVersion 1", first.Contains("\"schemaVersion\": 1"));

        var roundTripped = RulesJson.Parse(RulesJson.Serialize(rules));
        Check("rules round-trip", PlanJson.SerializeToString(RenamePlanner.Create(files, roundTripped)) == first);

        bool threw = false;
        try
        {
            RulesJson.Parse("{\"steps\":[{\"op\":\"nope\"}]}");
        }
        catch (RuleException)
        {
            threw = true;
        }
        Check("unknown op is rejected", threw);
    }

    // ------------------------------------------------------------------ helpers

    private static FileEntry Entry(string name)
        => new(name, new DateTime(2020, 1, 1), new DateTime(2020, 1, 1));

    private static void CheckPropose(string label, string fileName, ApplyTo applyTo, RuleStep[] steps, string expected)
    {
        var rules = new RuleSet { ApplyTo = applyTo };
        foreach (var step in steps)
        {
            rules.Steps.Add(step);
        }
        string actual = RenamePlanner.Propose(fileName, rules, 0);
        Check(label, actual == expected, actual + " (expected " + expected + ")");
    }

    private static void Check(string label, bool condition, string? detail = null)
    {
        if (condition)
        {
            _passed++;
            return;
        }
        Failures.Add(label + (detail is null ? string.Empty : ": " + detail));
    }
}

