using BatchRenameStudio.Core;

namespace BatchRenameStudio.Cli;

/// <summary>
/// The headless entry point. Exit codes: 0 success, 2 usage/rules error, 3 filesystem error.
/// In --plan mode the process is strictly read-only: it never renames anything.
/// </summary>
internal static class HeadlessRunner
{
    public const int ExitSuccess = 0;
    public const int ExitUsageError = 2;
    public const int ExitRuntimeError = 3;

    private static readonly HashSet<string> FlagSwitches =
        new(StringComparer.OrdinalIgnoreCase) { "plan", "apply", "help", "version" };

    private static readonly HashSet<string> ValueSwitches =
        new(StringComparer.OrdinalIgnoreCase) { "dir", "rules", "out" };

    /// <summary>True when the arguments ask for a headless run rather than the GUI.</summary>
    public static bool IsHeadless(string[] args)
    {
        foreach (string arg in args)
        {
            string normalized = arg.TrimStart('-', '/').ToLowerInvariant();
            int equals = normalized.IndexOf('=');
            if (equals >= 0)
            {
                normalized = normalized.Substring(0, equals);
            }
            if (normalized is "plan" or "apply" or "help" or "version" or "?" or "h")
            {
                return true;
            }
        }
        return false;
    }

    public static int Run(string[] args)
    {
        ConsoleBridge.Ensure();
        try
        {
            var command = CommandLine.Parse(args, FlagSwitches, ValueSwitches);

            if (command.Has("help"))
            {
                Console.Out.WriteLine(UsageText());
                return ExitSuccess;
            }

            if (command.Has("version"))
            {
                Console.Out.WriteLine("BatchRenameStudio 1.0 (plan schemaVersion " + Plan.CurrentSchemaVersion + ")");
                return ExitSuccess;
            }

            bool apply = command.Has("apply");
            if (!command.Has("plan") && !apply)
            {
                throw new CommandLineException("expected --plan or --apply");
            }
            if (command.Has("plan") && apply)
            {
                throw new CommandLineException("--plan and --apply are mutually exclusive");
            }

            string directory = Path.GetFullPath(command.Require("dir"));
            string rulesPath = command.Require("rules");
            string? outPath = apply ? command.Optional("out") : command.Require("out");

            if (!Directory.Exists(directory))
            {
                Console.Error.WriteLine("error: folder not found: " + directory);
                return ExitRuntimeError;
            }

            var rules = RulesJson.Load(rulesPath);
            var files = RenamePlanner.ReadFolder(directory);
            var plan = RenamePlanner.Create(files, rules);

            if (outPath is not null)
            {
                PlanJson.Write(outPath, plan);
            }

            if (apply)
            {
                var batch = RenameExecutor.Apply(directory, plan.Items);
                Console.Out.WriteLine("applied " + batch.Records.Count + " rename(s); " + plan.Summary);
                return ExitSuccess;
            }

            // Exactly one line on stdout, nothing else.
            Console.Out.WriteLine(plan.Summary + " -> " + Path.GetFullPath(outPath!));
            return ExitSuccess;
        }
        catch (CommandLineException ex)
        {
            Console.Error.WriteLine("error: " + ex.Message);
            Console.Error.WriteLine();
            Console.Error.WriteLine(UsageText());
            return ExitUsageError;
        }
        catch (RuleException ex)
        {
            Console.Error.WriteLine("error: " + ex.Message);
            return ExitUsageError;
        }
        catch (RenameFailure ex)
        {
            Console.Error.WriteLine("error: " + ex.Message);
            return ExitRuntimeError;
        }
        catch (Exception ex) when (ex is IOException or UnauthorizedAccessException or ArgumentException or NotSupportedException)
        {
            Console.Error.WriteLine("error: " + ex.Message);
            return ExitRuntimeError;
        }
    }

    private static string UsageText() =>
        """
        Batch Rename Studio

          BatchRenameStudio.exe
              Starts the graphical rule editor.

          BatchRenameStudio.exe --plan --dir <folder> --rules <rules.json> --out <plan.json>
              Writes the rename plan as UTF-8 JSON (no BOM) and renames nothing.
              Prints one summary line to stdout. Exit code 0 on success.

          BatchRenameStudio.exe --apply --dir <folder> --rules <rules.json> [--out <plan.json>]
              Same planning step, then performs every rename whose status is "ok".

          BatchRenameStudio.exe --help | --version
        """;
}

